gWg(){return"\u062a\u062e\u062a\u0644\u0641 \u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u0645\u0639\u0635\u0645 \u0639\u0646 \u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u062c\u0633\u0645 \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629\u061b \u0627\u0633\u062a\u062e\u062f\u0645\u0647\u0627 \u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u062a\u063a\u064a\u0651\u0631 \u0641\u0642\u0637."},
gwn(){return"\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a"},
LI(a){return"\u0639\u0645\u0631\u0643 \u0627\u0644\u0632\u0645\u0646\u064a "+a},
LU(a){var s="\u0623\u0635\u063a\u0631 \u0628\u0640 "+a
return A.cN(a,s+" \u0633\u0646\u0648\u0627\u062a",this.a,null,"\u0623\u0635\u063a\u0631 \u0628\u0633\u0646\u0629 \u0648\u0627\u062d\u062f\u0629",s+" \u0633\u0646\u0629","\u0623\u0635\u063a\u0631 \u0628\u0633\u0646\u062a\u064a\u0646",null)},
LM(a){var s="\u0623\u0643\u0628\u0631 \u0628\u0640 "+a
return A.cN(a,s+" \u0633\u0646\u0648\u0627\u062a",this.a,null,"\u0623\u0643\u0628\u0631 \u0628\u0633\u0646\u0629 \u0648\u0627\u062d\u062f\u0629",s+" \u0633\u0646\u0629","\u0623\u0643\u0628\u0631 \u0628\u0633\u0646\u062a\u064a\u0646",null)},
gLO(){return"\u0645\u0645\u0627\u062b\u0644 \u0644\u0639\u0645\u0631\u0643 \u0627\u0644\u0632\u0645\u0646\u064a"},
gLJ(){return"\u0623\u062f\u062e\u0644 \u0639\u0645\u0631\u0643 \u0641\u064a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 (18\u201390) \u0644\u0639\u0631\u0636 \u0639\u0645\u0631\u0643 \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a."},
LK(a){return"\u064a\u062d\u062a\u0627\u062c \u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a \u0625\u0644\u0649 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0646\u0628\u0636 \u0648\u0627\u0644\u062e\u0637\u0648\u0627\u062a \u0623\u0648 \u0627\u0644\u0646\u0648\u0645 \u0641\u064a "+a+" \u0623\u064a\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644 \u0645\u0646 \u0622\u062e\u0631 21 \u064a\u0648\u0645\u064b\u0627."},
gLN(){return"\u0646\u0628\u0636 \u0627\u0644\u0631\u0627\u062d\u0629"},
gLR(){return"\u0627\u0644\u062e\u0637\u0648\u0627\u062a \u0627\u0644\u064a\u0648\u0645\u064a\u0629"},
gLQ(){return"\u0646\u0648\u0645 \u0627\u0644\u0644\u064a\u0644"},
gLH(){return"\u0645\u0624\u0634\u0631 \u0643\u062a\u0644\u0629 \u0627\u0644\u062c\u0633\u0645"},
LT(a){return a+" \u0633\u0646\u0629"},
gLS(){return"\u0622\u062e\u0631 8 \u0623\u0633\u0627\u0628\u064a\u0639"},
gLL(){return"\u062a\u0642\u062f\u064a\u0631 \u062e\u0627\u0635 \u0628\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0646 \u0646\u0628\u0636 \u0627\u0644\u0631\u0627\u062d\u0629 \u0648\u0627\u0644\u062e\u0637\u0648\u0627\u062a \u0648\u0627\u0644\u0646\u0648\u0645 \u0648\u0645\u0624\u0634\u0631 \u0643\u062a\u0644\u0629 \u0627\u0644\u062c\u0633\u0645 \u062e\u0644\u0627\u0644 \u0622\u062e\u0631 21 \u064a\u0648\u0645\u064b\u0627\u061b \u0648\u0644\u064a\u0633 \u0642\u064a\u0627\u0633\u064b\u0627 \u0637\u0628\u064a\u064b\u0627."},
LP(a,b){return"\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a "+a+"\u060c "+b},
gxS(){return"\u0631\u0627\u062f\u0627\u0631 \u0627\u0644\u0635\u062d\u0629"},
