gV8(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0628\u064a\u0627\u0646\u0627\u062a \u0645\u0646 \u0627\u0644\u0644\u064a\u0644\u0629 \u0627\u0644\u0645\u0627\u0636\u064a\u0629. \u0627\u0631\u062a\u062f\u0650 \u0627\u0644\u0633\u0648\u0627\u0631 \u0644\u064a\u0644\u064b\u0627 \u0644\u064a\u0639\u0645\u0644 \u0627\u0644\u0631\u0627\u062f\u0627\u0631."},
gV4(){return"\u0643\u0627\u0646\u062a \u0627\u0644\u0644\u064a\u0644\u0629 \u0627\u0644\u0645\u0627\u0636\u064a\u0629 \u0636\u0645\u0646 \u0646\u0637\u0627\u0642\u0643 \u0627\u0644\u0645\u0639\u062a\u0627\u062f."},
gVd(){return"\u0627\u062e\u062a\u0644\u0641\u062a \u0642\u064a\u0645\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u0646 \u0627\u0644\u0644\u064a\u0644\u0629 \u0627\u0644\u0645\u0627\u0636\u064a\u0629 \u0639\u0646 \u0627\u0644\u0645\u0639\u062a\u0627\u062f."},
gVb(){return"\u062a\u063a\u064a\u0651\u0631\u062a \u0639\u062f\u0629 \u0642\u064a\u0645 \u0645\u0639\u064b\u0627. \u062e\u0630 \u0642\u0633\u0637\u064b\u0627 \u0645\u0646 \u0627\u0644\u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u0648\u0645\u060c \u0648\u0627\u0633\u062a\u0634\u0631 \u0637\u0628\u064a\u0628\u064b\u0627 \u0625\u0646 \u0634\u0639\u0631\u062a \u0628\u062a\u0648\u0639\u0643."},
V6(a,b){return"\u0646\u0628\u0636 \u0627\u0644\u0644\u064a\u0644 "+a+"\u060c \u0627\u0644\u0645\u0639\u062a\u0627\u062f "+b},
V7(a,b){return"HRV \u0627\u0644\u0644\u064a\u0644 "+a+"\u060c \u0627\u0644\u0645\u0639\u062a\u0627\u062f "+b},
Vc(a,b){return"\u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u0644\u064a\u0644 "+a+"\u060c \u0627\u0644\u0645\u0639\u062a\u0627\u062f "+b},
Va(a,b){return"\u0623\u0643\u0633\u062c\u064a\u0646 \u0627\u0644\u0644\u064a\u0644 "+a+"\u060c \u0627\u0644\u0645\u0639\u062a\u0627\u062f "+b},
gV9(){return"\u062a\u064f\u0642\u0627\u0631\u0646 \u0643\u0644 \u0644\u064a\u0644\u0629 \u0628\u0622\u062e\u0631 14 \u0644\u064a\u0644\u0629 \u0644\u062f\u064a\u0643. \u0644\u0627 \u064a\u0642\u062f\u0651\u0645 \u062a\u0634\u062e\u064a\u0635\u064b\u0627. \u0625\u0630\u0627 \u0634\u0639\u0631\u062a \u0628\u0623\u0644\u0645 \u0641\u064a \u0627\u0644\u0635\u062f\u0631 \u0623\u0648 \u0636\u064a\u0642 \u0641\u064a \u0627\u0644\u062a\u0646\u0641\u0633 \u0623\u0648 \u062f\u0648\u0627\u0631\u060c \u0641\u0627\u062a\u0635\u0644 \u0628\u0631\u0642\u0645 \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0627\u0644\u0645\u062d\u0644\u064a."},
gwd(){return"\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a"},
gKT(){return"\u062a\u0642\u0631\u064a\u0631 \u0634\u062e\u0635\u064a \u0639\u0646 \u0623\u0633\u0628\u0648\u0639\u0643 \u0645\u0639 \u0646\u0635\u0627\u0626\u062d."},
gKJ(){return"\u0647\u0630\u0627 \u062a\u0642\u0631\u064a\u0631 \u062a\u062c\u0631\u064a\u0628\u064a: \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u063a\u064a\u0631 \u0645\u062a\u0635\u0644 \u0628\u0639\u062f\u060c \u0644\u0630\u0627 \u0643\u062a\u0628\u062a \u0642\u0648\u0627\u0639\u062f \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0646\u0635. \u0644\u0645 \u062a\u063a\u0627\u062f\u0631 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0647\u0627\u062a\u0641\u0643."},
gKG(){return"\u0625\u0630\u0646 \u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a"},
gKz(){return"\u064a\u0643\u062a\u0628 \u0646\u0645\u0648\u0630\u062c \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a. \u0644\u0630\u0644\u0643 \u064a\u064f\u0631\u0633\u0644 \u0645\u0644\u062e\u0635 \u0623\u0633\u0628\u0648\u0639\u0643 \u0625\u0644\u0649 \u062e\u0627\u062f\u0645\u0646\u0627 \u0648\u0645\u0646\u0647 \u0625\u0644\u0649 \u0645\u0632\u0648\u0651\u062f \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a."},
gKF(){return"\u0645\u0627 \u064a\u064f\u0631\u0633\u0644"},
