gKC(){return"\u0645\u0627 \u0644\u0627 \u064a\u064f\u0631\u0633\u0644"},
gKB(){return"\u0627\u0633\u0645\u0643 \u0648\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0648\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0633\u0648\u0627\u0631 \u0648\u062a\u0633\u062c\u064a\u0644\u0627\u062a \u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0642\u0644\u0628 \u0627\u0644\u062e\u0627\u0645 \u0648\u0627\u0644\u0642\u064a\u0627\u0633\u0627\u062a \u0627\u0644\u0641\u0631\u062f\u064a\u0629."},
gKu(){return"\u0645\u0632\u0648\u0651\u062f \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a \u062e\u0627\u0631\u062c \u0627\u0644\u0628\u0644\u0627\u062f (\u0627\u0644\u0648\u0644\u0627\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u062d\u062f\u0629)\u060c \u0644\u0630\u0627 \u064a\u064f\u0646\u0642\u0644 \u0627\u0644\u0645\u0644\u062e\u0635 \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u0631\u062c. \u0644\u0627 \u064a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0632\u0648\u0651\u062f \u0647\u0630\u0647 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0644\u062a\u062f\u0631\u064a\u0628 \u0627\u0644\u0646\u0645\u0627\u0630\u062c."},
gKA(){return"\u0644\u0627 \u064a\u0634\u062e\u0651\u0635 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0648\u0644\u0627 \u064a\u0648\u0635\u064a \u0628\u0623\u062f\u0648\u064a\u0629\u060c \u0648\u0644\u0627 \u064a\u063a\u0646\u064a \u0639\u0646 \u0641\u062d\u0635 \u0627\u0644\u0637\u0628\u064a\u0628."},
gKD(){return"\u064a\u0645\u0643\u0646\u0643 \u0633\u062d\u0628 \u0627\u0644\u0625\u0630\u0646 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0634\u0627\u0634\u0629 \u0641\u064a \u0623\u064a \u0648\u0642\u062a. \u0628\u0639\u062f \u0630\u0644\u0643 \u0644\u0627 \u062a\u064f\u0643\u062a\u0628 \u062a\u0642\u0627\u0631\u064a\u0631 \u062c\u062f\u064a\u062f\u0629."},
gKw(){return"\u0623\u0648\u0627\u0641\u0642 \u0635\u0631\u0627\u062d\u0629\u064b \u0639\u0644\u0649 \u0646\u0642\u0644 \u0645\u0644\u062e\u0635\u064a \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u0631\u062c \u0644\u062a\u062d\u0644\u064a\u0644\u0647 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064a."},
gKv(){return"\u0627\u0644\u0633\u0645\u0627\u062d"},
gKx(){return"\u0644\u064a\u0633 \u0627\u0644\u0622\u0646"},
gKM(){return"\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u062a\u0642\u0631\u064a\u0631"},
gKS(){return"\u0625\u0646\u0634\u0627\u0621 \u0645\u0646 \u062c\u062f\u064a\u062f"},
